                    const source = Java.use('okio.Okio').source(responseBody.source());
                    const buffer = Java.use('okio.Buffer').$new();
                    source.readFully(buffer, responseBody.contentLength());
                    connInfo.responseBody = buffer.readUtf8();
                    console.log("Response Body:");
